using System;using System.IO;using System.Reflection;using System.Threading;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
class SecurityFixTests {
 static int checks,failures;static void Check(bool ok,string n){checks++;if(!ok)failures++;Console.WriteLine((ok?"PASS ":"FAIL ")+n);}
 static void Read(AssistantRuntime r){typeof(AssistantRuntime).GetMethod("ReadEvents",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(r,null);}
 [STAThread]static int Main(string[] args){var json=new JavaScriptSerializer();string root=Path.Combine(args[0],"run-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
 string input=Path.Combine(root,"import"),target=Path.Combine(root,"target");Directory.CreateDirectory(input);var config=new AssistantConfig();config.Monitor.Quota.Executable=Path.Combine(args[0],"BenignQuotaProbe.exe");config.Monitor.Quota.Home=root;File.WriteAllText(Path.Combine(input,"assistant.json"),json.Serialize(config));UserData.QueueImport(input,target);UserData.ApplyPending(target);var restored=json.Deserialize<AssistantConfig>(File.ReadAllText(Path.Combine(target,"assistant.json")));Check(restored.Monitor.Quota.Executable==""&&restored.Monitor.Quota.Home==""&&!restored.Monitor.Quota.Enabled,"pending import clears execution paths and disables quota");
 string migration=Path.Combine(root,"migration");UserData.ImportMissing(input,migration);restored=json.Deserialize<AssistantConfig>(File.ReadAllText(Path.Combine(migration,"assistant.json")));Check(restored.Monitor.Quota.Executable==""&&!restored.Monitor.Quota.Enabled,"first upgrade migration also removes executable trust");
 string queue=Path.Combine(root,"events");Directory.CreateDirectory(queue);Environment.SetEnvironmentVariable("CONAN_PET_EVENT_DIR",queue);var runtime=new AssistantRuntime(root,root);try{
 string unrelated=Path.Combine(queue,"project.json"),invalid=Path.Combine(queue,Guid.NewGuid().ToString("N")+".json");File.WriteAllText(unrelated,"{\"project\":\"keep me\"}");File.WriteAllText(invalid,"{bad");Read(runtime);Check(File.Exists(unrelated)&&File.Exists(invalid),"event reader preserves unrelated and malformed JSON");
 string legacy=Path.Combine(queue,Guid.NewGuid().ToString("N")+".json");File.WriteAllText(legacy,json.Serialize(new{@event="SessionStart",session="legacy",utc=DateTime.UtcNow.ToString("o")}));Read(runtime);Check(!File.Exists(legacy)&&runtime.Codex.Tasks.ContainsKey("legacy"),"well formed legacy GUID events remain compatible");
 string owned=Path.Combine(queue,"conan-event-"+Guid.NewGuid().ToString("N")+".json");File.WriteAllText(owned,json.Serialize(new{protocol="conan-event-v1",@event="PermissionRequest",session="owned",utc=DateTime.UtcNow.ToString("o")}));Read(runtime);Check(!File.Exists(owned)&&runtime.Codex.Tasks.ContainsKey("owned"),"versioned bridge event is processed and consumed");
 var fresh=new AssistantConfig();fresh.Monitor.Quota.Executable=Path.Combine(args[0],"BenignQuotaProbe.exe");string isolated=Path.Combine(root,"runtime-data");Directory.CreateDirectory(isolated);File.WriteAllText(Path.Combine(isolated,"assistant.json"),json.Serialize(fresh));string marker=Path.Combine(args[0],"executed.marker");if(File.Exists(marker))File.Delete(marker);var second=new AssistantRuntime(root,isolated);try{var state=second.QuotaReader.Sample(second.Config.Monitor.Quota);Thread.Sleep(700);Check(!File.Exists(marker),"unapproved configured program never starts in background");}finally{second.Telemetry.Dispose();second.Limiter.Dispose();}
 }finally{runtime.Telemetry.Dispose();runtime.Limiter.Dispose();}

 string approvedData=Path.Combine(root,"approved-data"),probe=Path.Combine(root,"approved-probe.exe");File.Copy(Path.Combine(args[0],"BenignQuotaProbe.exe"),probe);var trust=new QuotaExecutionTrust(approvedData);var identity=trust.Inspect(probe,root);trust.Approve(identity);using(var permit=trust.OpenVerified(probe,root)){Check(permit.Identity.Sha256==identity.Sha256,"explicit program grant verifies exact executable identity");bool locked=false;try{File.AppendAllText(probe,"change");}catch(IOException){locked=true;}Check(locked,"verified executable remains locked against replacement during use");}
 var approvedReader=new CodexQuotaReader(approvedData);approvedReader.Sample(new CodexQuotaConfig{Executable=probe,Home=root});string approvedMarker=Path.Combine(root,"executed.marker");for(int i=0;i<40&&!File.Exists(approvedMarker);i++)Thread.Sleep(50);Check(File.Exists(approvedMarker),"explicitly approved harmless program can still be launched");Thread.Sleep(200);
 bool otherHome=false;try{using(trust.OpenVerified(probe,input)){}}catch(IOException){otherHome=true;}Check(otherHome,"approval cannot be reused with another Codex data directory");File.AppendAllText(probe,"changed after approval");bool changed=false;try{using(trust.OpenVerified(probe,root)){}}catch(IOException){changed=true;}Check(changed,"changed executable content invalidates prior approval");trust.Revoke();Check(!File.Exists(Path.Combine(approvedData,"quota-program-trust.dat")),"program grant can be explicitly revoked");
 Check(!File.Exists(Path.Combine(target,"quota-program-trust.dat")),"configuration import never creates an executable grant");
 string genuine=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"genuine-limit");Directory.CreateDirectory(genuine);foreach(string file in LimiterSecurity.Files)File.Copy(Path.Combine(args[0],"..","..","work","offline-pet","dist","network-limit",file),Path.Combine(genuine,file),true);using(LimiterSecurity.Verify(genuine)){Check(true,"genuine newly built limiter components match embedded hashes");bool locked=false;try{File.AppendAllText(Path.Combine(genuine,"WinDivert.dll"),"tamper");}catch(IOException){locked=true;}Check(locked,"preflight gate holds component handles against modification");}
 string bootstrap=LimiterSecurity.Script(genuine,123,.5,"Local\\ConanBandwidth-test");Check(bootstrap.Contains("ConanDesktopAssistant.Security")&&bootstrap.Contains("Assert-Protected")&&bootstrap.Contains("Source component hash mismatch")&&bootstrap.Contains("Protected component hash mismatch"),"embedded bootstrap verifies copied bytes and protected ACLs");Check(Path.IsPathRooted(LimiterSecurity.PowerShell)&&LimiterSecurity.PowerShell.EndsWith("WindowsPowerShell\\v1.0\\powershell.exe"),"elevation targets system PowerShell by absolute path");
 bool remote=false;try{CodexQuotaReader.FindExecutable(@"\\127.0.0.1\unused\probe.exe");}catch(ArgumentException){remote=true;}catch(IOException){remote=false;}Check(remote,"network executable path rejected before file access");
 var verify=typeof(DownloadLimiter).GetMethod("VerifyComponents",BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic);Check(verify!=null,"limiter exposes pre-elevation integrity gate");if(verify!=null){string bad=Path.Combine(root,"tampered");Directory.CreateDirectory(bad);foreach(var name in new[]{"ConanBandwidth.exe","WinDivert.dll","WinDivert64.sys"})File.WriteAllText(Path.Combine(bad,name),"untrusted");bool rejected=false;try{verify.Invoke(null,new object[]{bad});}catch(TargetInvocationException e){rejected=e.InnerException is IOException;}Check(rejected,"tampered limiter files rejected without UAC or driver loading");}
 }catch(Exception e){failures++;Console.WriteLine(e);}Directory.CreateDirectory(args[0]);File.WriteAllText(Path.Combine(args[0],"security-fix-results.json"),json.Serialize(new{checks,failures,production_settings_changed=false,driver_loaded=false}));return failures==0?0:1;}
}
